import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = records[1:]
    width = max([5, len(columns)] + [len(row) for row in rows])
    used_names = set(columns)

    for index in range(len(columns), width):
        name = f"column_{index + 1}"
        suffix = 2
        while name in used_names:
            name = f"column_{index + 1}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
